#' Compare DiD Estimators
#'
#' Compares difference-in-differences estimators on one panel: two-way fixed 
#' effects, Callaway and Sant'Anna, Sun and Abraham, Borusyak-Jaravel-Spiess, 
#' Gardner and stacked DiD, with overall and event-study effects.
#'
#' @examples
#' \donttest{
#' # d is a data frame with one row per unit and period
#' didcompare(data = d, dep = 'y', id = 'id', time = 'year', treat = 'D')
#'}
#' @param data .
#' @param dep a string naming the outcome variable in \code{data}
#' @param id a string naming the unit identifier variable in \code{data}
#' @param time a string naming the period variable in \code{data}; values must
#'   be integers (a year or a period number)
#' @param treat a string naming the treatment variable in \code{data}: a 0/1
#'   indicator that never turns off, or the first treated period (see
#'   \code{treatType})
#' @param covs a vector of strings naming covariates in \code{data}
#'   (optional); text and factor variables are dummy-coded
#' @param cluster a string naming a cluster variable that is constant within
#'   units (optional); by default standard errors are clustered by unit
#' @param weights a string naming a positive weight variable that is constant
#'   within units (optional), for example a baseline population; not used by the
#'   Borusyak-Jaravel-Spiess estimator
#' @param treatType \code{'indicator'} (default) if \code{treat} is a 0/1
#'   treatment indicator, or \code{'cohort'} if it holds the first treated
#'   period (0 or missing = never treated)
#' @param twfe \code{TRUE} (default) or \code{FALSE}, estimate two-way fixed
#'   effects (static and event study)
#' @param cs \code{TRUE} (default) or \code{FALSE}, estimate Callaway and
#'   Sant'Anna group-time effects
#' @param sa \code{TRUE} (default) or \code{FALSE}, estimate Sun and Abraham
#'   interaction-weighted effects (never-treated controls)
#' @param bjs \code{TRUE} (default) or \code{FALSE}, estimate the Borusyak,
#'   Jaravel and Spiess imputation estimator
#' @param gardner \code{TRUE} (default) or \code{FALSE}, estimate Gardner's
#'   two-stage estimator
#' @param stacked \code{TRUE} (default) or \code{FALSE}, estimate stacked
#'   difference-in-differences with clean controls
#' @param csControl \code{'nevertreated'} (default) or \code{'notyettreated'},
#'   the control group used by Callaway and Sant'Anna
#' @param csMethod \code{'dr'} (default), \code{'ipw'} or \code{'reg'}, the
#'   estimation method used with covariates
#' @param bootstrap \code{TRUE} or \code{FALSE} (default), use the multiplier
#'   bootstrap for Callaway and Sant'Anna standard errors
#' @param bootReps the number of bootstrap draws (default 999)
#' @param seed the random seed used for the bootstrap (default 1234)
#' @param showForest \code{TRUE} (default) or \code{FALSE}, show the forest
#'   plot of overall effects
#' @param showGT \code{TRUE} or \code{FALSE} (default), show the Callaway and
#'   Sant'Anna group-time effects as a heat map
#' @param aggGroup \code{TRUE} or \code{FALSE} (default), tabulate Callaway
#'   and Sant'Anna effects by cohort
#' @param aggCalendar \code{TRUE} or \code{FALSE} (default), tabulate Callaway
#'   and Sant'Anna effects by calendar time
#' @param showCode \code{TRUE} or \code{FALSE} (default), show an R script
#'   that reproduces the results
#' @param minE the most negative event time shown (default -4)
#' @param maxE the largest event time shown (default 4)
#' @param ciLevel the confidence level in percent (default 95)
#' @param plotPalette \code{'color'} (default, colour-blind safe) or
#'   \code{'gray'} (shades, shapes and line types for printing)
#' @param plotCI \code{'bars'} (default) or \code{'ribbon'}, draw confidence
#'   intervals as error bars or shaded bands
#' @param plotDodge the horizontal spacing between estimators when intervals
#'   are drawn as error bars (default 0.5)
#' @param showHelp \code{TRUE} or \code{FALSE} (default), show notes on what
#'   the method does and how to read the results
#' @param showGuide \code{TRUE} or \code{FALSE} (default), show a guide to the
#'   variables and the data format
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$info} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dynamic} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$forest} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$groupTab} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$calTab} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$gtPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$code} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
didcompare <- function(
    data,
    dep,
    id,
    time,
    treat,
    covs = NULL,
    cluster = NULL,
    weights = NULL,
    treatType = "indicator",
    twfe = TRUE,
    cs = TRUE,
    sa = TRUE,
    bjs = TRUE,
    gardner = TRUE,
    stacked = TRUE,
    csControl = "nevertreated",
    csMethod = "dr",
    bootstrap = FALSE,
    bootReps = 999,
    seed = 1234,
    showForest = TRUE,
    showGT = FALSE,
    aggGroup = FALSE,
    aggCalendar = FALSE,
    showCode = FALSE,
    minE = -4,
    maxE = 4,
    ciLevel = 95,
    plotPalette = "color",
    plotCI = "bars",
    plotDodge = 0.5,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("didcompare requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(id)) id <- jmvcore::resolveQuo(jmvcore::enquo(id))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(id), id, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- didcompareOptions$new(
        dep = dep,
        id = id,
        time = time,
        treat = treat,
        covs = covs,
        cluster = cluster,
        weights = weights,
        treatType = treatType,
        twfe = twfe,
        cs = cs,
        sa = sa,
        bjs = bjs,
        gardner = gardner,
        stacked = stacked,
        csControl = csControl,
        csMethod = csMethod,
        bootstrap = bootstrap,
        bootReps = bootReps,
        seed = seed,
        showForest = showForest,
        showGT = showGT,
        aggGroup = aggGroup,
        aggCalendar = aggCalendar,
        showCode = showCode,
        minE = minE,
        maxE = maxE,
        ciLevel = ciLevel,
        plotPalette = plotPalette,
        plotCI = plotCI,
        plotDodge = plotDodge,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- didcompareClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

